'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const HERO_HEADLINES=[['Your course, ','under control','.'],['Stay ','ahead',' of every deadline.'],['One place for ','everything',' that matters.'],['Know exactly ','what’s next','.'],['Built to keep you ','on track','.'],['Your day, ','sorted','.'],['Never guess ','what to do next','.'],['Study time, ','well spent','.']];
function heroHeadline(){const [a,b,c]=HERO_HEADLINES[Math.floor(Math.random()*HERO_HEADLINES.length)];return `${html(a)}<span class="accent-green">${html(b)}</span>${html(c)}`}
const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
let state={progress:{},entries:[],settings:{}},library=[],calendar={events:[]},route='',dirty=false,queue=Promise.resolve(),toastTimer;
const dayKey=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const parseDay=s=>new Date(s+'T12:00:00Z');
const plus=(s,n)=>{const d=parseDay(s);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const fmt=s=>s?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/London'}).format(parseDay(s)):'Date to confirm';
const clock=s=>new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/London'}).format(new Date(s));
const monday=s=>plus(s,-((parseDay(s).getUTCDay()+6)%7));
function weekDate(sem,w){if(sem===1)return plus('2026-09-21',(w-1)*7);return plus('2027-01-25',(w-1)*7+(w>8?14:0));}
function teaching(s){for(let sem of [1,2])for(let week=1;week<=12;week++){const d=weekDate(sem,week);if(s>=d&&s<=plus(d,6))return {sem,week}}return null;}
function defaultWeek(){const t=dayKey();return t<'2026-09-21'?'2026-09-21':monday(t)}
let selectedWeek=defaultWeek();
const mod=id=>PLAN.modules.find(m=>m.code===id);
const topics=code=>PLAN.topics.filter(t=>t.module===code);
const progress=id=>state.progress[id]||{status:'new',checks:[],notes:''};
const covered=t=>t.content.reduce((n,_,i)=>n+(progress(t.id).checks?.includes(i)?1:0),0);
function coverage(code){let ts=code?topics(code):PLAN.topics;return {done:ts.reduce((n,t)=>n+covered(t),0),total:ts.reduce((n,t)=>n+t.content.length,0)};}
function meter(code){let c=coverage(code);return `<div class="progress"><i style="width:${c.total?c.done/c.total*100:0}%"></i></div><div class="progress-label">${c.done} / ${c.total} content items covered${!c.total?' · syllabus pending':''}</div>`}
const CONF_LABELS=['New to this','Seen it before','Fairly confident','Know it well'];
const PRIORITY_LABELS=['Low','Normal','High','Urgent'];
const REVIEW_STEPS=[1,3,7,16,35,60,90];
const confidence=code=>state.settings.diagnostic?.[code]??1;
const modPriority=code=>state.settings.priorities?.[code]??1;
const topicConfidence=t=>{const p=progress(t.id);return p.confidence??confidence(t.module);};
function weightValue(a){const n=parseFloat(a.weight);return isNaN(n)?10:n;}
function daysUntil(dateStr){return Math.round((parseDay(dateStr)-parseDay(dayKey()))/864e5);}
function estMinutes(t){return Math.max(15,Math.min(60,(t.content.length||3)*4));}
function nextAssessmentFor(code){let scored=PLAN.assessments.filter(a=>a.module===code).map(a=>{let p=progress('assessment-'+a.id);if(p.submitted)return null;let [,e]=p.due?[p.due,p.due]:assessWindow(a);return {a,date:e};}).filter(Boolean);scored.sort((x,y)=>x.date.localeCompare(y.date));return scored[0]||null;}
function assessmentBoost(t,score,reason){const near=nextAssessmentFor(t.module);if(near){const d=daysUntil(near.date);if(d<=21){const urgency=d<=0?42:Math.max(0,40-d*1.9);score+=urgency;reason.push(d<=0?`${near.a.title} deadline has passed — resolve or update it`:`${near.a.title} is due in ${d} day${d===1?'':'s'}`);}}const ns=nextSessions().find(e=>e.module===t.module);if(ns){const d=Math.floor((new Date(ns.start)-new Date())/864e5);if(d<=2){score+=16;reason.push(`your next ${t.module} session is ${d<=0?'today':d===1?'tomorrow':'in '+d+' days'}`);}}return score;}
function topicScore(t){
  const p=progress(t.id);
  if(p.known||p.status==='solid')return null;
  if(p.snoozed&&p.snoozed>=dayKey())return null;
  const total=t.content.length||1,done=covered(t),gap=1-done/total;
  let score=8*gap+2;
  score*=[0.5,1,1.4,2][p.priority??1];
  score*=[0.55,1,1.3,1.7][modPriority(t.module)];
  score+=[14,7,3,0][topicConfidence(t)];
  const reason=[];
  score=assessmentBoost(t,score,reason);
  if(done>0&&done<total)reason.push(`${done} of ${total} content items already covered`);
  else if(done===0)reason.push('not started yet');
  if((p.priority??1)>=2)reason.push('you flagged this as '+PRIORITY_LABELS[p.priority].toLowerCase()+' priority');
  if(topicConfidence(t)<=1)reason.push('you rated your confidence here as low');
  return {t,score,reason,minutes:estMinutes(t),kind:'learn'};
}
function reviewScore(t){
  const p=progress(t.id);
  if(p.known||p.status!=='solid')return null;
  if(!p.reviewDue||p.reviewDue>dayKey())return null;
  const overdue=daysUntil(p.reviewDue);
  let score=6+Math.min(20,Math.max(0,-overdue)*0.6);
  score*=[0.5,1,1.4,2][p.priority??1];
  score*=[0.55,1,1.3,1.7][modPriority(t.module)];
  const reason=[overdue<0?`review was due ${-overdue} day${overdue===-1?'':'s'} ago`:'review is due today',`marked solid, reviewed ${p.reviews||1} time${(p.reviews||1)===1?'':'s'}`];
  score=assessmentBoost(t,score,reason);
  return {t,score,reason,minutes:Math.max(10,Math.round(estMinutes(t)*0.4)),kind:'review'};
}
function bestNext(limit=5){return PLAN.topics.map(topicScore).filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,limit);}
function reviewQueue(limit=10){return PLAN.topics.map(reviewScore).filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,limit);}
function dailyPlan(){const budget=state.settings.dailyMinutes||120;const picks=[...bestNext(30),...reviewQueue(15)].sort((a,b)=>b.score-a.score);const plan=[];let used=0;for(const item of picks){if(plan.length&&used+item.minutes>budget)continue;plan.push(item);used+=item.minutes;if(used>=budget)break;}if(!plan.length&&picks.length)plan.push(picks[0]);return {plan,used,budget};}
function nextReviewDate(reviews){return plus(dayKey(),REVIEW_STEPS[Math.min(reviews,REVIEW_STEPS.length-1)]);}
function streakDays(){const days=new Set(state.entries.filter(e=>['study','reflection','task'].includes(e.type)&&(e.minutes>0||e.type!=='task')).map(e=>e.date));let n=0,d=dayKey();if(!days.has(d))d=plus(d,-1);while(days.has(d)){n++;d=plus(d,-1);}return n;}
function weekMinutes(){const start=monday(dayKey());return state.entries.filter(e=>e.type!=='task'&&e.date>=start&&e.date<=plus(start,6)).reduce((n,e)=>n+(e.minutes||0),0);}
function dayActivity(){const by={};for(const e of state.entries){if(e.type==='task'&&e.category==='event')continue;by[e.date]=(by[e.date]||0)+(e.minutes||0)+(e.minutes?0:e.type==='task'?0:8);}return by;}
function heatLevel(m){return m<=0?0:m<30?1:m<75?2:m<150?3:4;}
function heatmap(weeks=18){const by=dayActivity(),startCol=plus(monday(dayKey()),-(weeks-1)*7),today=dayKey();let months='',lastMonth='';let cols='';for(let w=0;w<weeks;w++){const colStart=plus(startCol,w*7);const label=new Intl.DateTimeFormat('en-GB',{month:'short'}).format(parseDay(colStart));months+=`<span class="heat-month">${label!==lastMonth?label:''}</span>`;lastMonth=label;let cells='';for(let d=0;d<7;d++){const day=plus(colStart,d);if(day>today){cells+='<span class="heat-cell heat-empty"></span>';continue;}const m=by[day]||0;cells+=`<span class="heat-cell l${heatLevel(m)}" title="${fmt(day)}${m?' · '+m+' min logged':' · nothing logged'}"></span>`;}cols+=`<div class="heat-col">${cells}</div>`;}return `<div class="heatmap-wrap"><div class="heat-months">${months}</div><div class="heatmap">${cols}</div><div class="heat-legend"><span>Less</span><span class="heat-cell l0"></span><span class="heat-cell l1"></span><span class="heat-cell l2"></span><span class="heat-cell l3"></span><span class="heat-cell l4"></span><span>More</span></div></div>`;}
function confButtons(code){return `<div class="pill-row" data-conf-group="${code}">${CONF_LABELS.map((l,i)=>`<button type="button" class="pill ${confidence(code)===i?'active':''}" data-conf="${code}" data-val="${i}">${l}</button>`).join('')}</div>`}
function priButtons(code){return `<div class="pill-row" data-pri-group="${code}">${PRIORITY_LABELS.map((l,i)=>`<button type="button" class="pill ${modPriority(code)===i?'active':''}" data-modpri="${code}" data-val="${i}">${l}</button>`).join('')}</div>`}
function topicConfButtons(id){const cur=progress(id).confidence??'';return `<div class="pill-row" data-topicconf-group="${id}">${CONF_LABELS.map((l,i)=>`<button type="button" class="pill small ${cur===i?'active':''}" data-topicconf="${id}" data-val="${i}">${l}</button>`).join('')}</div>`}
const STATUS_LABELS=[['new','New'],['learning','Learning'],['solid','Solid']];
function statusButtons(id){const cur=progress(id).status||'new';return `<div class="pill-row" data-status-group="${id}">${STATUS_LABELS.map(([v,l])=>`<button type="button" class="pill ${cur===v?'active':''}" data-topicstatus="${id}" data-status="${v}">${l}</button>`).join('')}</div>`}
function topicPriButtons(id){const cur=progress(id).priority??1;return `<div class="pill-row" data-topicpri-group="${id}">${PRIORITY_LABELS.map((l,i)=>`<button type="button" class="pill small ${cur===i?'active':''}" data-topicpri="${id}" data-val="${i}">${l}</button>`).join('')}</div>`}
async function api(url,data){const r=await fetch(url,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:undefined);let result;try{result=await r.json()}catch{throw Error('The local server did not respond correctly. Keep this page open and restart the launcher.')}if(!r.ok)throw Error(result.error||'Could not save.');return result;}
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.classList.toggle('error',error);el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',error?7000:2600)}
function save(kind,id,record){const next=queue.then(async()=>{const d=await api('/api/save',{kind,id,record:typeof record==='function'?record():record});if(kind==='progress')state.progress[d.id]=d.record;if(kind==='settings')state.settings=d.record;if(kind==='entry'){let i=state.entries.findIndex(e=>e.id===d.id);if(i<0)state.entries.push(d.record);else state.entries[i]=d.record}return d});queue=next.catch(()=>{});return next;}
function moduleOptions(current='',all=true){return (all?'<option value="">All modules / general</option>':'')+PLAN.modules.map(m=>`<option value="${m.code}" ${m.code===current?'selected':''}>${m.code} · ${html(m.title)}</option>`).join('')}
function head(eyebrow,title,subtitle='',actions=''){return `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${actions}</section>`}
function shell(content){const part=route.split('/')[0];const links=[['home','Today'],['modules','Modules'],['week','Week'],['tasks','Tasks'],['journal','Journal'],['settings','Settings']];const modSub=['module','topic','focus','assessment','assessments','source','sources','degree'];return `<aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark">f.</span> fieldnotes</a><div class="workspace-label">YOUR COURSE ORGANISER</div><nav>${links.map(([id,name])=>`<a class="${part===id||(id==='modules'&&modSub.includes(part))||(id==='tasks'&&part==='task')?'active':''}" href="#${id}">${name}</a>`).join('')}</nav><div class="sidebar-foot">BSc Artificial Intelligence<br>Oxford Brookes · 2026–27<span class="save-label">Progress saved on this Mac</span></div></aside><main><header><span>YOUR COURSE, IN ONE PLACE</span><span class="quiet">${fmt(dayKey())} · Europe/London</span></header>${content}</main>`}
function sourceMatches(query){return library.filter(s=>s.path.includes(query))}
function sourceLinks(query){return sourceMatches(query).map(s=>`<a class="source-link" href="#source/${s.id}">${html(s.name)} ↗</a>`).join('')||'<span class="quiet">Source not available in this snapshot.</span>'}
function moduleSources(code){if(code==='INDUCTION')return library.filter(s=>/05 Computing Induction|07 Academic|10 Use of AI|general\//.test(s.path));if(['COMP4005','COMP4006'].includes(code))return sourceMatches('Subject Introduction Slides - Year 1');return library.filter(s=>s.module===code);}
function unitTime(t){return t.weeks[0]===0?'Induction / ongoing':`Semester ${t.sem} · Week ${t.weeks.join(', ')}`}
function topicRow(t){return `<a class="topic-row" href="#topic/${t.id}"><div><span class="tag">${unitTime(t)}</span><h3>${html(t.title)}</h3><p>${t.module} · ${t.content.length} content items</p></div><span class="progress-label">${covered(t)} / ${t.content.length} →</span></a>`}
function prepList(id,items){return items.map((text,i)=>{let checked=progress(id).checks?.includes(i);return `<label class="check ${checked?'done':''}"><input type="checkbox" data-check="${id}" data-index="${i}" ${checked?'checked':''}><span>${html(text)}</span></label>`}).join('')}
function assessWindow(a){if(a.id==='m-exam')return ['2027-05-04','2027-05-14'];let start=weekDate(a.sem,a.week);return a.day===null?[start,plus(start,4)]:[plus(start,a.day),plus(start,a.day)];}
function assessmentDate(a){const p=progress('assessment-'+a.id);if(p.due)return `${fmt(p.due)}${p.time?' · '+html(p.time):''} · your confirmed date`;let [s,e]=assessWindow(a);return `${s===e?fmt(s):fmt(s)+' – '+fmt(e)} · ${a.id==='m-exam'?'exam window':'derived from teaching week'}`}
function assessmentCard(a){const p=progress('assessment-'+a.id);return `<article class="panel"><div class="actions"><span class="tag">${a.module} · ${a.weight}</span><span class="tag ${p.submitted?'good':'warn'}">${p.submitted?'Recorded as completed':p.due?'Date entered by you':'Exact deadline to confirm'}</span></div><h3 style="margin-top:15px">${a.title}</h3><p class="deadline">${assessmentDate(a)}</p><p>${a.detail}</p><div class="actions"><a class="button small secondary" href="#assessment/${a.id}">Manage assessment →</a></div></article>`}
function unresolvedTasks(){return state.entries.filter(e=>e.type==='task'&&!e.resolved&&e.category!=='event')}
function nextSessions(){return allSessions().filter(e=>e.start.slice(0,10)>=dayKey()).sort((a,b)=>a.start.localeCompare(b.start)).slice(0,3)}
function sessionCard(e){return `<article class="event"><span class="tag">${html(e.module)} · ${html(e.source||'Your timetable entry')}</span><h3>${html(e.title)}</h3><p>${fmt(e.start.slice(0,10))} · ${clock(e.start)}–${clock(e.end)}</p><p>${html(e.location||'Room not entered')}</p><a class="source-link" href="#module/${e.module}">Module content →</a></article>`}
function queueCard(p,i){return `<article class="panel${i===0?' focus':''}"><div class="actions"><span class="tag">${p.kind==='review'?'REVIEW':'#'+(i+1)} · ${html(p.t.module)}</span><span class="tag">${unitTime(p.t)}</span><span class="tag ${p.kind==='review'?'good':''}">~${p.minutes} min</span></div><h2 style="margin-top:15px">${html(p.t.title)}</h2><p>${html(p.reason.join(' · ')||'Ready to start.')}</p><div class="actions"><a class="button small" href="#topic/${p.t.id}">Open →</a>${p.kind==='review'?'':`<button type="button" class="button secondary small" data-snooze="${p.t.id}">Snooze 2 days</button>`}${topicPriButtons(p.t.id)}</div></article>`}
function focusHero(){const {plan,used,budget}=dailyPlan();if(!plan.length)return '<section class="panel focus"><p class="eyebrow">DO THIS NEXT</p><h2>Nothing queued.</h2><p>Everything is marked known, solid or snoozed. Open a module to unlock more topics, or revisit something for review.</p></section>';const top=plan[0];return `<section class="panel focus"><p class="eyebrow">DO THIS NEXT · ${html(top.t.module)}${top.kind==='review'?' · REVIEW':''}</p><h2>${html(top.t.title)}</h2><p>${html(top.reason.join(' · ')||'Ready to start — no prep recorded yet.')}</p><div class="actions"><a class="button" href="#topic/${top.t.id}">Start now →</a>${top.kind==='review'?'':`<button type="button" class="button secondary small" data-snooze="${top.t.id}">Not today</button>`}<a class="text-link" href="#focus">See the full queue →</a></div>${plan.length>1?`<div class="path-preview">${plan.slice(1,4).map(p=>`<span><a class="text-link" style="color:inherit" href="#topic/${p.t.id}">${html(p.t.module)} · ${html(p.t.title)} · ~${p.minutes}m</a></span>`).join('')}</div>`:''}<p class="small" style="margin-top:16px;color:#dae3e9">Today's plan: ${plan.length} item${plan.length===1?'':'s'} · ~${used} of your ${budget}-minute target</p></section>`}
function focusPage(){const {plan,used,budget}=dailyPlan();const learn=bestNext(20),review=reviewQueue(20);return head('BEST NEXT TASK','Your ranked queue.','Ranked by deadline pressure, module priority, prior knowledge, coverage gaps and spaced review — recalculated every time you tick, snooze or calibrate something.')+`<section class="panel dark"><p class="eyebrow">TODAY'S PLAN</p><div class="big-number">${used}<small> / ${budget} min target</small></div><p>${plan.length} item${plan.length===1?'':'s'} picked to fit your daily target — highest-ranked first, learning before review.</p></section><section class="section"><div class="section-title"><h2>Learn next</h2><span class="quiet">${learn.length} queued</span></div>${learn.length?`<div class="stack">${learn.map(queueCard).join('')}</div>`:'<div class="empty">Nothing left to learn — everything is known, solid or snoozed.</div>'}</section>${review.length?`<section class="section"><div class="section-title"><h2>Due for review</h2><span class="quiet">${review.length} due</span></div><div class="stack">${review.map(queueCard).join('')}</div></section>`:''}<section class="section panel"><h2>How this is ranked</h2><p class="small muted">Each topic starts from its coverage gap, then scales by the priority you set on the topic and on its module, by how confident you said you already are (module-wide, or overridden per topic), and by how close its linked assessment deadline or next timetabled session is. Marking a topic “already known” or a coverage item complete removes it from the queue; snoozing hides it for two days. Marking a topic solid schedules a spaced review — 1, 3, 7, 16, 35, 60 then 90 days later — which resurfaces it here when due.</p><a class="source-link" href="#modules">Calibrate module confidence & priority on each module page →</a></section>`}
function overview(){let c=coverage(),t=teaching(dayKey()),focus=PLAN.topics.filter(x=>x.sem===(t?.sem||1)&&x.weeks.includes(t?.week||1));let tasks=unresolvedTasks().sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);let streak=streakDays(),mins=weekMinutes(),target=(state.settings.dailyMinutes||120)*7;return head(t?`SEMESTER ${t.sem} · WEEK ${t.week}`:'INDUCTION & FORWARD PLANNING',heroHeadline(),'Content to cover, work to finish and dates to confirm.',`<a class="button hero-cta" href="#week">Open week planner →</a>`)+`<div class="stats"><div class="stat"><b>${c.done}/${c.total}</b><span>Content items covered</span></div><div class="stat"><b>${unresolvedTasks().length}</b><span>Your open tasks</span></div><div class="stat"><b>${PLAN.assessments.filter(a=>!progress('assessment-'+a.id).due&&!progress('assessment-'+a.id).submitted).length}</b><span>Assessment dates to confirm</span></div></div>${focusHero()}<div class="two-col"><div class="stack"><section class="panel"><div class="section-title"><h2>Work to follow up</h2><a href="#tasks" class="text-link">All tasks →</a></div><form id="quick-task-form" class="quick-add"><label class="field"><span class="sr-only">What needs doing?</span><input name="text" required placeholder="Add a task — e.g. Finish Week 1 practical"></label><label class="field" style="flex:0 0 150px"><span class="sr-only">Target date</span><input type="date" name="date" value="${dayKey()}"></label><button class="button small">Add</button></form>${tasks.length?tasks.map(taskCard).join(''):'<p class="quiet">Nothing open. Add tasks from new Moodle announcements, practical sheets and project briefs.</p>'}</section><section class="panel"><p class="eyebrow">${t?'THIS WEEK’S CONTENT':'PREPARE FOR WEEK 1'}</p>${focus.map(topicRow).join('')}<a class="source-link" href="#modules">View every module and topic →</a></section></div><div class="stack"><section class="panel"><p class="eyebrow">NEXT IN YOUR CALENDAR</p>${nextSessions().map(sessionCard).join('')||'<p>No upcoming imported sessions.</p>'}<a class="source-link" href="#week">Full timetable →</a></section><section class="panel"><div class="section-title"><h2>Your activity</h2><span class="quiet">${streak} day streak</span></div>${heatmap()}<p class="small muted" style="margin-top:12px">${mins} of ${target} minutes logged this week</p></section></div></div>`}
function modulesPage(){return head('YEAR 1 · YOUR MODULES','The complete course view.','Open a module for preparation, individual topic pages, weekly work and assessments.',`<div class="actions"><a class="button secondary small" href="#assessments">All assessments →</a><a class="button secondary small" href="#sources">Sources →</a><a class="button secondary small" href="#degree">Degree map →</a></div>`)+`<div class="module-grid">${PLAN.modules.map(m=>`<article class="panel module-card"><span class="module-meta">${m.code} · ${m.term?'Semester '+m.term:'Across the year'}</span><h2>${m.title}</h2><p>${topics(m.code).length?topics(m.code).length+' topic pages mapped from your materials':'Detailed syllabus not supplied yet'}</p>${meter(m.code)}<div class="actions"><a href="#module/${m.code}" class="button small">Open module →</a></div></article>`).join('')}</div>`}
function modulePage(code){const m=mod(code);if(!m)return missing();let ts=topics(code);let acts=PLAN.assessments.filter(a=>a.module===code);return `<div class="breadcrumb"><a href="#modules">My modules</a> / ${code}</div>`+head(code,m.title,m.term?'Semester '+m.term:'Across the academic year')+`<div class="two-col"><div><section class="panel"><h2>Before starting this module</h2><p class="quiet">Your preparation checklist · planning suggestions based on the available material.</p>${prepList('prep-'+code,m.prep)}</section><section class="section"><div class="section-title"><h2>Content breakdown</h2><span class="quiet">${ts.length} topic pages</span></div>${ts.length?ts.map(topicRow).join(''):`<div class="notice">The source snapshot does not include this module’s teaching plan. The module remains in your organiser so you can track new work and dates.</div><a class="button secondary" href="#tasks/${code}">Add published work →</a>`}</section></div><div class="stack"><section class="panel"><h2>Module record</h2><p>${m.info}</p>${meter(code)}<a href="#tasks/${code}" class="source-link">Tasks for this module →</a></section><section class="panel"><h2>Calibrate this module</h2><p class="quiet">Sets how hard the Best next task queue works to surface ${code} for you.</p><p class="small muted" style="margin-bottom:6px">How well do you already know this?</p>${confButtons(code)}<p class="small muted" style="margin:16px 0 6px">How much does this matter to you right now?</p>${priButtons(code)}</section><section class="panel"><h2>Source documents</h2>${moduleSources(code).map(s=>`<a class="source-link" href="#source/${s.id}">${html(s.name)}</a><br>`).join('')}</section></div></div><section class="section"><div class="section-title"><h2>Assessments & key dates</h2></div><div class="module-grid">${acts.map(assessmentCard).join('')||'<div class="empty">No assessment brief or confirmed deadline in the supplied files.</div>'}</div></section>`}
function topicPage(id){let t=PLAN.topics.find(x=>x.id===id);if(!t)return missing();let p=progress(id),index=PLAN.topics.findIndex(x=>x.id===id),next=PLAN.topics[index+1];return `<div class="breadcrumb"><a href="#modules">My modules</a> / <a href="#module/${t.module}">${t.module}</a> / ${html(t.title)}</div>`+head(unitTime(t),t.title,`${t.module} · ${covered(t)} of ${t.content.length} content items covered`)+`<div class="two-col"><div class="stack"><section class="panel"><h2>Content to cover</h2><p class="quiet">Tick each item when you have covered it. This records coverage, not a grade.</p>${prepList(id,t.content)}</section><section class="panel"><h2>Priority & prior knowledge</h2><p class="small muted" style="margin-bottom:6px">Status</p>${statusButtons(id)}<p class="small muted" style="margin:16px 0 6px">How urgent is this topic for you?</p>${topicPriButtons(id)}<p class="small muted" style="margin:16px 0 6px">Your confidence in this specific topic (overrides the module rating)</p>${topicConfButtons(id)}<label class="check ${p.known?'done':''}" style="margin-top:6px"><input type="checkbox" id="known-toggle" data-known="${id}" ${p.known?'checked':''}><span>I already know this — skip it in the Best next task queue</span></label>${p.status==='solid'?`<div class="notice info" style="margin-top:16px"><b>${p.reviewDue&&p.reviewDue>dayKey()?`Next review ${fmt(p.reviewDue)}.`:'Review due now.'}</b> Reviewed ${p.reviews||0} time${(p.reviews||0)===1?'':'s'}.<div class="actions" style="margin-top:12px"><button type="button" class="button small secondary" data-reviewed="${id}">I reviewed this today →</button></div></div>`:''}</section><section class="panel"><h2>Topics learnt & follow-up notes</h2><form data-note="${id}"><label class="field"><span>Keep your notes, file references and remaining work here</span><textarea name="notes" rows="6">${html(p.notes)}</textarea></label><button class="button small">Save notes</button><span class="save-state" role="status"></span></form></section></div><aside class="stack"><section class="panel"><h2>Before this topic</h2>${prepList('prep-'+id,t.prep)}</section><section class="panel"><h2>Practical work & things to achieve</h2><p>${t.work}</p><a class="button small secondary" href="#tasks/${t.module}">Add a follow-up task</a></section>${t.pcc?`<section class="panel"><p class="eyebrow">REVISION CROSS-REFERENCE</p><p>${t.pcc}</p><a class="source-link" href="https://ehmatthes.github.io/pcc_2e/" target="_blank" rel="noreferrer">PCC second-edition resources ↗</a><p class="small muted">Book reference only. The university topic list defines the course coverage. PCC 2e chapter 11 uses unittest; pytest is supplementary.</p></section>`:''}<section class="panel"><h3>Source</h3>${sourceLinks(t.source)}</section>${next?.module===t.module?`<a class="button secondary" href="#topic/${next.id}">Next: ${next.title} →</a>`:''}</aside></div>`}
function assessmentPage(id){let a=PLAN.assessments.find(a=>a.id===id);if(!a)return missing();let p=progress('assessment-'+id),timed=id==='p-test'||id==='m-exam';return `<div class="breadcrumb"><a href="#assessments">Assessments</a> / ${a.module}</div>`+head(a.module+' · '+a.weight,a.title,assessmentDate(a))+`<div class="two-col"><section class="panel"><h2>Requirements & preparation</h2><p>${a.detail}</p><div class="notice">The supplied guide identifies a teaching week or exam window. The displayed calendar date is derived from the semester dates and is not a confirmed Moodle submission timestamp.</div>${prepList('assessment-'+id,timed?['Read the test or examination instructions','Confirm the date, start time, room and duration','Check permitted materials and equipment','Review the assessed topic coverage','Complete the test or examination','Record results and follow-up work']:['Read the actual assessment brief and marking criteria','Record the exact deadline and submission location','Complete the required work','Check submission format and required files','Submit through the university system','Keep the submission receipt','Read feedback and record follow-up work'])}</section><section class="panel"><h2>Your assessment record</h2><form id="assessment-form" data-id="${id}"><label class="field"><span>Confirmed date from your brief</span><input name="due" type="date" value="${html(p.due||'')}"></label><label class="field"><span>Deadline / start time (London)</span><input type="time" name="time" value="${html(p.time||'')}"></label><label class="field"><span>Brief / submission link</span><input type="url" name="url" value="${html(p.url||'')}" placeholder="https://moodle.brookes.ac.uk/…"></label><label class="field"><span>Notes / mark / feedback</span><textarea name="notes">${html(p.notes)}</textarea></label><label class="check"><input name="submitted" type="checkbox" ${p.submitted?'checked':''}><span>${timed?'I have completed this test or examination':'I have submitted this through the university system'}</span></label><button class="button small">Save assessment record</button><p class="save-state" role="status"></p></form>${safeUrl(p.url)?`<a class="source-link" href="${html(safeUrl(p.url))}" target="_blank" rel="noreferrer">Open saved assessment link ↗</a>`:''}</section></div>`}
function assessmentsPage(){return head('TESTS · PROJECTS · COURSEWORK','Know what is due.','Teaching-week dates are planning estimates until you confirm the Moodle deadline.')+`<div class="toolbar"><label>Module<select id="assessment-filter">${moduleOptions()}</select></label></div><div class="module-grid" id="assessment-list">${PLAN.assessments.map(assessmentCard).join('')}</div>`}
function taskCard(e){return `<article class="event task ${e.resolved?'muted':''}"><span class="tag">${html(e.topic||'General')} · ${e.resolved?'Complete':e.date<dayKey()?'Past target date':'Open'}</span><h3>${html(e.text)}</h3><p>Target: ${fmt(e.date)}${e.minutes?' · '+e.minutes+' min planned':''}</p>${e.detail?`<p>${html(e.detail)}</p>`:''}<div class="actions"><button class="button small secondary" data-resolve="${e.id}">${e.resolved?'Reopen':'Mark complete'}</button><a class="source-link" href="#task/${e.id}">Edit →</a></div></article>`}
function taskForm(entry={},module=''){return `<form id="task-form" data-id="${entry.id||''}" class="panel"><h2>${entry.id?'Edit task':'Add work to track'}</h2><label class="field"><span>What needs doing?</span><input name="text" required value="${html(entry.text||'')}" placeholder="Complete Week 1 practical"></label><label class="field"><span>Module</span><select name="topic">${moduleOptions(entry.topic||module)}</select></label><div class="inline"><label class="field"><span>Target date</span><input type="date" name="date" required value="${entry.date||dayKey()}"></label><label class="field"><span>Estimated minutes</span><input name="minutes" type="number" min="0" max="1440" value="${entry.minutes||0}"></label></div><label class="field"><span>Details / source / deliverables</span><textarea name="detail">${html(entry.detail||'')}</textarea></label><button class="button">Save task</button><p class="save-state" role="status"></p></form>`}
function tasksPage(code=''){return head('YOUR WORK QUEUE','Everything to follow through.','Add practicals, projects, preparation and admin as they are released.')+`<div class="two-col"><div><div class="toolbar"><label>Module<select id="task-filter">${moduleOptions(code)}</select></label><label>Show<select id="task-state"><option value="open">Open tasks</option><option value="all">All tasks</option><option value="done">Completed tasks</option></select></label></div><div id="task-list"></div></div>${taskForm({},code)}</div>`}
function fillTasks(){let module=$('#task-filter')?.value||'',status=$('#task-state')?.value||'open';let es=state.entries.filter(e=>e.type==='task'&&e.category!=='event'&&(!module||e.topic===module)&&(status==='all'||(status==='done'?e.resolved:!e.resolved))).sort((a,b)=>a.date.localeCompare(b.date));$('#task-list').innerHTML=es.map(taskCard).join('')||'<p class="empty">No matching tasks. Add work using the form.</p>';}
function allSessions(){const manual=state.entries.filter(e=>e.category==='event'&&!e.resolved);let events=[...calendar.events];for(const e of manual){for(let d=e.date;d<=(e.repeat==='weekly'?e.until:e.date);d=plus(d,7)){if(d>plus(e.date,366))break;const offset=(d>='2026-10-25'&&d<'2027-03-28')?'+00:00':'+01:00';events.push({id:e.id+'-'+d,module:e.topic,title:e.text,start:d+'T'+e.startTime+':00'+offset,end:d+'T'+e.endTime+':00'+offset,location:e.location,source:'Your timetable entry'})}}return events;}
function weekContent(){let t=teaching(selectedWeek);let unit=PLAN.topics.filter(x=>t&&x.sem===t.sem&&x.weeks.includes(t.week));let sessions=allSessions().filter(e=>e.start.slice(0,10)>=selectedWeek&&e.start.slice(0,10)<=plus(selectedWeek,6));let task=unresolvedTasks().filter(e=>e.date>=selectedWeek&&e.date<=plus(selectedWeek,6));let assessments=PLAN.assessments.filter(a=>{let p=progress('assessment-'+a.id),[s,e]=p.due?[p.due,p.due]:assessWindow(a);return !p.submitted&&s<=plus(selectedWeek,6)&&e>=selectedWeek});return `<div class="section-title"><h2>${fmt(selectedWeek)} – ${fmt(plus(selectedWeek,6))}</h2><span class="tag">${t?'Semester '+t.sem+' · Week '+t.week:'Outside teaching weeks'}</span></div><div class="week-days">${Array.from({length:7},(_,i)=>{let d=plus(selectedWeek,i),es=sessions.filter(e=>e.start.slice(0,10)===d),tasks=task.filter(e=>e.date===d);return `<section class="day"><p class="date-title">${new Intl.DateTimeFormat('en-GB',{weekday:'long'}).format(parseDay(d))} · ${fmt(d)}</p>${es.map(sessionCard).join('')}${tasks.map(taskCard).join('')}${!es.length&&!tasks.length?'<div class="empty">No recorded sessions or tasks.</div>':''}</section>`}).join('')}</div><section class="section"><h2>Content scheduled in the module guides</h2>${unit.map(topicRow).join('')||'<p class="empty">No published topic sequence for this selected week.</p>'}</section>${t?.sem===1?`<section class="panel section"><h2>COMP4004 weekly work</h2><p>The handbook expects weekly lab exercises and quizzes to be completed that week. From Week 2, track released portfolio exercises too. Your specific practical times are not in the calendar snapshot.</p>${prepList('weekly-1-'+t.week,['Complete this week’s released lab work','Complete this week’s released quiz, if provided','Update portfolio work released this week','Check Moodle for new instructions and feedback'])}</section>`:''}<section class="section"><h2>Assessment milestones this week</h2><div class="module-grid">${assessments.map(assessmentCard).join('')||'<div class="empty">No recorded assessment milestone this week.</div>'}</div></section><section class="panel section"><h2>Suggested order for independent work</h2><p class="small muted">A personal planning suggestion around your teaching. Your ${state.settings.dailyMinutes||120}-minute daily revision target is additional planning guidance, not the university’s total workload.</p><div class="study-plan"><div><b>Before each session</b>Open the linked module topic and cover the preparation items you still need.</div><div><b>After the session</b>Tick content covered and add practical or follow-up work with a target date.</div><div><b>Before the week ends</b>Complete released labs/quizzes and review assessment progress. Check the next week’s topic list.</div></div></section>`}
function weekPage(){return head('TEACHING · WORK · PREPARATION','Your week, connected.','Calendar times are shown in Europe/London.',`<a class="button secondary" href="https://cloud.timeedit.net/uk_obu/web/students/" target="_blank" rel="noreferrer">Check live TimeEdit ↗</a>`)+`<div class="notice">Calendar snapshot checked ${calendar.checked}, covering Semester 1 and Semester 2 through 14 May 2027. It contains 35 lectures for COMP4004, COMP4009 and COMP4005. Practical allocations and COMP4035, MATH4004 and COMP4006 sessions are unconfirmed here. TimeEdit takes precedence over Google Calendar. This local snapshot does not automatically refresh.</div><div class="toolbar"><button class="button secondary small" data-week="-7">← Previous</button><label>Week containing<input id="week-date" type="date" value="${selectedWeek}"></label><button class="button secondary small" data-week="7">Next →</button><button class="button secondary small" id="current-week">Current / next teaching week</button></div><div id="week-content">${weekContent()}</div><section class="section panel"><details><summary>Add a missing timetable session</summary><form id="event-form"><div class="inline"><label class="field"><span>Session title</span><input name="text" required placeholder="Programming practical"></label><label class="field"><span>Module</span><select name="topic">${moduleOptions('',false)}</select></label></div><div class="inline"><label class="field"><span>First date</span><input name="date" type="date" min="2026-09-01" max="2027-08-31" required value="${selectedWeek}"></label><label class="field"><span>Start time (London)</span><input name="startTime" type="time" required></label><label class="field"><span>End time (London)</span><input name="endTime" type="time" required></label></div><label class="field"><span>Room / location</span><input name="location"></label><div class="inline"><label class="field"><span>Repeat</span><select name="repeat"><option value="once">Once</option><option value="weekly">Weekly</option></select></label><label class="field"><span>Repeat until</span><input name="until" type="date" min="2026-09-01" max="2027-08-31" value="2026-12-11"></label></div><p class="small muted">For a recurring semester 2 session, make separate entries before and after the Easter break.</p><button class="button small">Add session locally</button><p class="save-state" role="status"></p></form></details></section><section class="section"><h2>Manually added sessions</h2>${state.entries.filter(e=>e.category==='event'&&!e.resolved).map(e=>`<article class="event"><h3>${html(e.text)}</h3><p>${e.topic} · ${fmt(e.date)} · ${e.startTime}–${e.endTime}${e.repeat==='weekly'?' weekly through '+fmt(e.until):''}</p><button class="button small secondary" data-resolve="${e.id}">Archive this session</button></article>`).join('')||'<p class="quiet">None yet.</p>'}</section>`}
function journalPage(){return head('YOUR RECORD','Work done. Topics learnt.','Record study time, practical outcomes, feedback and things to follow up.')+`<div class="two-col"><div class="entries stack">${state.entries.filter(e=>e.type!=='task').slice().reverse().map(e=>`<article class="panel"><span class="tag">${html(e.topic||'General')} · ${fmt(e.date)} · ${e.minutes} min · ${e.type}</span><p style="margin-top:15px">${html(e.text)}</p></article>`).join('')||'<div class="empty">Your study history will appear here.</div>'}</div><form id="log-form" class="panel"><h2>Add a study record</h2><label class="field"><span>Module</span><select name="topic">${moduleOptions()}</select></label><label class="field"><span>Record type</span><select name="type"><option value="study">Study / content covered</option><option value="reflection">Practical / project reflection</option><option value="error">Problem or error</option><option value="question">Question for teaching staff</option></select></label><div class="inline"><label class="field"><span>Date</span><input type="date" name="date" required value="${dayKey()}"></label><label class="field"><span>Minutes studied</span><input name="minutes" type="number" min="0" max="1440" value="0"></label></div><label class="field"><span>Topics learnt, work done or feedback</span><textarea name="text" required rows="7"></textarea></label><button class="button small">Save study record</button><p class="save-state" role="status"></p></form></div>`}
function sourcesPage(){return head('59 SUPPLIED DOCUMENT EXTRACTS','Your source library.','Local copies of the provided files. Snapshot captured 15 September 2026; check Moodle for new material.')+`<div class="toolbar"><label>Find a document<input id="source-search" type="search" placeholder="Title, module or folder"></label><label>Scope<select id="source-scope"><option value="current">Current & reference</option><option value="all">All documents</option><option value="archive">Historical programmes</option></select></label></div><div class="panel" id="source-list"></div>`}
function fillSources(){const q=$('#source-search').value.toLowerCase(),scope=$('#source-scope').value;let rows=library.filter(s=>(scope==='all'||(scope==='archive'?s.historical:!s.historical))&&s.path.toLowerCase().includes(q));$('#source-list').innerHTML=rows.map(s=>`<div class="source-row"><span class="tag ${s.historical?'warn':''}">${s.historical?'Historical · not current requirements':s.module}</span><h3><a href="#source/${s.id}">${html(s.name)}</a></h3><p>${html(s.path)}</p></div>`).join('')||'<p>No documents match this filter.</p>'}
function sourcePage(id){const s=library.find(x=>x.id===id);if(!s)return missing();return `<div class="breadcrumb"><a href="#sources">Source library</a></div>`+head(s.historical?'HISTORICAL DOCUMENT':'SUPPLIED SOURCE EXTRACT',html(s.name),html(s.path))+`<div class="notice info">This is a text extraction. Diagrams, equations, links and layout may be incomplete. Use the original Moodle file when those details matter.</div><a class="source-link" href="${s.url}" download>Download text extract ↓</a><pre id="source-text" class="source-text">Loading document…</pre>`}
function degreePage(){return head('BSC ARTIFICIAL INTELLIGENCE','The wider degree.','Current Year 1 induction identifies these later modules. Their future teaching plans and dates are not supplied.')+`<div class="module-grid">${PLAN.future.map(([year,...names])=>`<article class="panel"><h2>${year}</h2><ul class="list-plain">${names.map(n=>`<li>${n}</li>`).join('')}</ul><p class="small muted">No future assessment dates are scheduled from historical documents.</p></article>`).join('')}</div><section class="panel section"><h2>Optional placement</h2><p>COMP5015 Work Experience Placement sits between second and final taught years in the induction diagram. Track careers and placement preparation through the induction module.</p><a class="source-link" href="#module/INDUCTION">Preparation & university admin →</a>${sourceLinks('Subject Introduction Slides - Year 1')}</section>`}
function settingsPage(){return head('LOCAL RECORDS','Keep your course record safe.','Export includes your checklists, tasks, timetable additions, notes and assessment records.')+`<section class="panel"><h2>Before teaching starts</h2><p class="quiet">A one-off checklist for the start of term.</p>${prepList('home-prep',['Check your practical groups in TimeEdit','Open each module and its preparation list','Complete induction and academic integrity requirements','Record newly published deadlines from Moodle'])}</section><div class="two-col"><section class="panel"><h2>Backup & restore</h2><a class="button secondary" href="/api/export">Export all saved work ↓</a><p style="margin-top:18px">Restore replaces saved progress and entries with your chosen backup. The server keeps a copy of the existing record before replacement.</p><label class="field"><span>Choose a portal JSON backup</span><input type="file" id="restore-file" accept="application/json,.json"></label><button class="button secondary small" id="restore">Restore selected backup</button><p class="save-state" id="restore-status" role="status"></p></section><section class="panel"><h2>Personal planning</h2><form id="settings-form"><label class="field"><span>Daily independent revision target (minutes)</span><input name="dailyMinutes" type="number" min="15" max="480" value="${state.settings.dailyMinutes||120}"></label><label class="field"><span>Your personal TimeEdit link, if available</span><input type="url" name="timetableUrl" value="${html(state.settings.timetableUrl||'')}" placeholder="https://cloud.timeedit.net/…"></label><button class="button small">Save preferences</button><p class="save-state" role="status"></p></form>${safeUrl(state.settings.timetableUrl)?`<a class="source-link" href="${html(safeUrl(state.settings.timetableUrl))}" target="_blank" rel="noreferrer">Open personal timetable ↗</a>`:''}<p class="small muted">The local portal does not log into Moodle or automatically sync Google Calendar. Use the source links to check updates. Calendar data was read on 17 September 2026.</p></section></div><section class="panel section legacy"><h2>Earlier revision notes</h2><p>Records from the previous Python drill pages remain saved. They are not treated as completed university content.</p>${Object.entries(state.progress).filter(([id])=>['pcc1','pcc2','pcc3','pcc4','bridge','extensions','degree','maths'].includes(id)).map(([id,p])=>`<details><summary>${id} · ${html(p.status)}</summary><p>${html(p.notes||'No notes entered.')}</p><p>Previously checked drill indices: ${html((p.checks||[]).join(', '))}</p></details>`).join('')||'<p class="quiet">No earlier notes found.</p>'}</section>`}
function missing(){return head('PAGE NOT FOUND','Choose a module to continue.','This topic may have moved.',`<a class="button" href="#modules">My modules →</a>`)}
async function render(){dirty=false;route=location.hash.slice(1)||'home';if(route==='curriculum'||route==='diagnostic'||route.startsWith('lesson-'))route='modules';if(route==='roadmap')route='degree';const [page,id]=route.split('/');let content;try{content=page==='home'?overview():page==='focus'?focusPage():page==='modules'?modulesPage():page==='module'?modulePage(id):page==='topic'?topicPage(id):page==='assessments'?assessmentsPage():page==='assessment'?assessmentPage(id):page==='tasks'?tasksPage(id):page==='task'?taskForm(state.entries.find(e=>e.id===id)||{}):page==='week'?weekPage():page==='journal'?journalPage():page==='sources'?sourcesPage():page==='source'?sourcePage(id):page==='degree'?degreePage():page==='settings'?settingsPage():missing();$('#app').innerHTML=shell(content);bind();if(page==='tasks')fillTasks();if(page==='sources')fillSources();if(page==='source'){const s=library.find(x=>x.id===id);if(s){let r=await fetch(s.url);if(!r.ok)throw Error('Could not load this source.');const text=await r.text();if(route==='source/'+id)$('#source-text').textContent=text;}}}catch(e){toast(e.message,true)}}
function formAction(form,action){form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])'),status=form.querySelector('.save-state');if(button)button.disabled=true;try{await action(new FormData(form));dirty=false;if(status){status.textContent='Saved on your Mac.';status.classList.remove('error')}}catch(err){if(status){status.textContent=err.message;status.classList.add('error')}toast(err.message,true)}finally{if(button)button.disabled=false}})}
function bind(){
  $$('form input, form textarea, form select').forEach(el=>el.addEventListener('input',()=>dirty=true));
  $$('[data-check]').forEach(el=>el.addEventListener('change',async()=>{const id=el.dataset.check,i=+el.dataset.index,on=el.checked;el.disabled=true;try{await save('progress',id,()=>{let p=progress(id),checks=new Set(p.checks||[]);on?checks.add(i):checks.delete(i);return {...p,checks:[...checks]}});el.closest('label').classList.toggle('done',on);toast('Checklist saved');}catch(e){el.checked=!on;toast(e.message,true)}finally{el.disabled=false}}));
  $$('[data-conf]').forEach(el=>el.addEventListener('click',async()=>{const code=el.dataset.conf,val=+el.dataset.val;el.disabled=true;try{await save('settings','main',()=>({...state.settings,diagnostic:{...state.settings.diagnostic,[code]:val}}));$$(`[data-conf-group="${code}"] .pill`).forEach(b=>b.classList.toggle('active',+b.dataset.val===val));toast('Confidence saved')}catch(e){toast(e.message,true)}finally{el.disabled=false}}));
  $$('[data-modpri]').forEach(el=>el.addEventListener('click',async()=>{const code=el.dataset.modpri,val=+el.dataset.val;el.disabled=true;try{await save('settings','main',()=>({...state.settings,priorities:{...state.settings.priorities,[code]:val}}));$$(`[data-pri-group="${code}"] .pill`).forEach(b=>b.classList.toggle('active',+b.dataset.val===val));toast('Priority saved')}catch(e){toast(e.message,true)}finally{el.disabled=false}}));
  $$('[data-topicpri]').forEach(el=>el.addEventListener('click',async()=>{const id=el.dataset.topicpri,val=+el.dataset.val;el.disabled=true;try{await save('progress',id,()=>({...progress(id),priority:val}));$$(`[data-topicpri-group="${id}"] .pill`).forEach(b=>b.classList.toggle('active',+b.dataset.val===val));toast('Priority saved')}catch(e){toast(e.message,true)}finally{el.disabled=false}}));
  $$('[data-topicconf]').forEach(el=>el.addEventListener('click',async()=>{const id=el.dataset.topicconf,val=+el.dataset.val;el.disabled=true;try{await save('progress',id,()=>({...progress(id),confidence:val}));$$(`[data-topicconf-group="${id}"] .pill`).forEach(b=>b.classList.toggle('active',+b.dataset.val===val));toast('Confidence saved')}catch(e){toast(e.message,true)}finally{el.disabled=false}}));
  $$('[data-topicstatus]').forEach(el=>el.addEventListener('click',async()=>{const id=el.dataset.topicstatus,val=el.dataset.status;el.disabled=true;try{await save('progress',id,()=>{const cur=progress(id);return {...cur,status:val,reviewDue:val==='solid'?(cur.reviewDue||nextReviewDate(cur.reviews||0)):cur.reviewDue};});$$(`[data-status-group="${id}"] .pill`).forEach(b=>b.classList.toggle('active',b.dataset.status===val));toast('Status saved');await render()}catch(e){toast(e.message,true)}finally{el.disabled=false}}));
  $('[data-reviewed]')?.addEventListener('click',async()=>{const el=$('[data-reviewed]'),id=el.dataset.reviewed;el.disabled=true;try{await save('progress',id,()=>{const cur=progress(id),reviews=(cur.reviews||0)+1;return {...cur,reviews,reviewDue:nextReviewDate(reviews)};});toast('Review logged');await render()}catch(e){toast(e.message,true);el.disabled=false}});
  $$('[data-known]').forEach(el=>el.addEventListener('change',async()=>{const id=el.dataset.known,on=el.checked;el.disabled=true;try{await save('progress',id,()=>({...progress(id),known:on}));el.closest('label').classList.toggle('done',on);toast(on?'Marked as already known':'Back in the queue')}catch(e){el.checked=!on;toast(e.message,true)}finally{el.disabled=false}}));
  $$('[data-snooze]').forEach(el=>el.addEventListener('click',async()=>{const id=el.dataset.snooze;el.disabled=true;try{await save('progress',id,()=>({...progress(id),snoozed:plus(dayKey(),2)}));toast('Snoozed for 2 days');await render()}catch(e){toast(e.message,true);el.disabled=false}}));
  $$('form[data-note]').forEach(form=>formAction(form,async f=>{await save('progress',form.dataset.note,()=>({...progress(form.dataset.note),notes:f.get('notes')}))}));
  if($('#assessment-form'))formAction($('#assessment-form'),async f=>{const id='assessment-'+$('#assessment-form').dataset.id;await save('progress',id,()=>({...progress(id),due:f.get('due'),time:f.get('time'),url:f.get('url'),notes:f.get('notes'),submitted:f.get('submitted')==='on'}));toast('Assessment record saved')});
  if($('#task-form'))formAction($('#task-form'),async f=>{let id=$('#task-form').dataset.id,old=state.entries.find(e=>e.id===id)||{};await save('entry',id||undefined,{...old,type:'task',text:f.get('text'),topic:f.get('topic'),date:f.get('date'),minutes:+f.get('minutes'),detail:f.get('detail'),resolved:old.resolved||false});toast('Task saved');dirty=false;await render()});
  if($('#quick-task-form')){formAction($('#quick-task-form'),async f=>{await save('entry',undefined,{type:'task',text:f.get('text'),topic:'',date:f.get('date')||dayKey(),minutes:0,resolved:false});toast('Task added');dirty=false;await render()});$('#quick-task-form input[name=text]')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#quick-task-form').requestSubmit();}});}
  if($('#log-form'))formAction($('#log-form'),async f=>{await save('entry',undefined,{type:f.get('type'),text:f.get('text'),topic:f.get('topic'),date:f.get('date'),minutes:+f.get('minutes')});toast('Study record saved');dirty=false;await render()});
  if($('#event-form'))formAction($('#event-form'),async f=>{if(f.get('endTime')<=f.get('startTime'))throw Error('End time must be after start time.');if(f.get('repeat')==='weekly'&&f.get('until')<f.get('date'))throw Error('Repeat-until must follow the first session.');await save('entry',undefined,{type:'task',category:'event',text:f.get('text'),topic:f.get('topic'),date:f.get('date'),minutes:0,startTime:f.get('startTime'),endTime:f.get('endTime'),location:f.get('location'),repeat:f.get('repeat'),until:f.get('until'),resolved:false});dirty=false;toast('Timetable session saved');await render()});
  if($('#settings-form'))formAction($('#settings-form'),async f=>{await save('settings','main',{...state.settings,dailyMinutes:+f.get('dailyMinutes'),timetableUrl:f.get('timetableUrl')})});
  $('#task-filter')?.addEventListener('change',fillTasks);$('#task-state')?.addEventListener('change',fillTasks);
  $('#source-search')?.addEventListener('input',fillSources);$('#source-scope')?.addEventListener('change',fillSources);
  $('#assessment-filter')?.addEventListener('change',e=>{$('#assessment-list').innerHTML=PLAN.assessments.filter(a=>!e.target.value||a.module===e.target.value).map(assessmentCard).join('')||'<p class="empty">No assessment details supplied for this module.</p>'});
  $$('[data-week]').forEach(b=>b.addEventListener('click',()=>{selectedWeek=plus(selectedWeek,+b.dataset.week);render()}));
  $('#week-date')?.addEventListener('change',e=>{if(e.target.value){selectedWeek=monday(e.target.value);render()}});
  $('#current-week')?.addEventListener('click',()=>{selectedWeek=defaultWeek();render()});
  $('#restore')?.addEventListener('click',async()=>{try{const file=$('#restore-file').files[0];if(!file)throw Error('Choose a backup first.');const data=JSON.parse(await file.text());if(!confirm('Replace current saved records with this backup? A copy of the current records will be kept on disk.'))return;await api('/api/import',data);state=await api('/api/state');dirty=false;toast('Backup restored');render()}catch(e){$('#restore-status').textContent=e.message;$('#restore-status').classList.add('error')}});
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-resolve]');if(b){let record=state.entries.find(x=>x.id===b.dataset.resolve);b.disabled=true;try{await save('entry',record.id,{...record,resolved:!record.resolved});if($('#task-list'))fillTasks();else render();toast(record.resolved?'Reopened':'Marked complete / archived')}catch(err){toast(err.message,true);b.disabled=false}}const link=e.target.closest('a[href^="#"]');if(link&&dirty&&!confirm('Leave this page without saving the form?'))e.preventDefault();});
addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
addEventListener('hashchange',()=>{render();scrollTo({top:0})});
(async()=>{try{[state,library,calendar]=await Promise.all([api('/api/state'),api('/sources.json'),api('/timetable.json')]);render()}catch(e){$('#app').innerHTML=`<div class="loading"><h1>Open the local organiser.</h1><p>${location.protocol==='file:'?'This page needs its local server. Double-click Start Study Portal.command, then open the address below.':html(e.message)}</p><a href="http://127.0.0.1:8765/">http://127.0.0.1:8765/</a></div>`}})();
